def get_gemini_api_key():
    api_key = None
    try:
        if hasattr(st, 'secrets'):
            api_key = st.secrets.get('GEMINI_API_KEY') or st.secrets.get('GEMINT_API_KEY')
    except Exception:
        pass
    if not api_key:
        api_key = os.environ.get('GEMINI_API_KEY') or os.environ.get('GEMINT_API_KEY')
    return api_key

