        sel_months = MONTHS[month_start_idx:12]
        
        # Dynamically compute exact monthly numbers from verified Excel database
        cur_year_dev = [0.0] * 12
        cur_year_con = [0.0] * 12
        
        if raw_sales_df is not None:
            if "2024" in year_sel:
                m_sub_df = raw_sales_df[raw_sales_df['Year_int'] == 2024]
